window.AUTH=window.AUTH||{};window.AUTH["19-1414"]={"d":"19-1414","id":"2020/19-1414","n":"United States v. Cooley","briefs":[{"k":"petitioner","label":"Brief of petitioner United States","date":"2021-01-08","url":"https://www.supremecourt.gov/DocketPDF/19/19-1414/165737/20210108153036386_19-1414tsUnitedStates.pdf","side":"pet","n":63},{"k":"respondent","label":"Brief of respondent Joshua James Cooley","date":"2021-02-12","url":"https://www.supremecourt.gov/DocketPDF/19/19-1414/168888/20210212123501425_Cooley%20Respondent%20Brief_FINAL.pdf","side":"res","n":41},{"k":"reply","label":"Reply of petitioner United States","date":"2021-03-12","url":"https://www.supremecourt.gov/DocketPDF/19/19-1414/171761/20210312122720663_19-1414%20Cooley%20Reply.pdf","side":"pet","n":45}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/593us2r40_j5fl.pdf","tr":true,"items":[{"t":"case","label":"Arizona v. United States","cite":"567 U.S. 387","y":2012,"id":"2011/11-182","sc":1,"sum":"The Court found that Arizona's state immigration provisions conflicted in part with federal immigration laws.","sumSrc":"Oyez","by":{"0":"18","1":"17, 18","2":"3"}},{"t":"case","label":"Atkinson Trading Co. v. Shirley","cite":"532 U.S. 645","y":2001,"id":"2000/00-454","sc":1,"op":2,"ar":4,"sum":"The Court held that the Navajo Nation's imposition of a hotel occupancy tax upon nonmembers on non-Indian fee land within its reservation is invalid.","sumSrc":"Oyez","by":{"0":"24","1":"14, 24","2":"11, 13"}},{"t":"case","label":"Atwater v. City of Lago Vista","cite":"532 U.S. 318","y":2001,"id":"2000/99-1408","sc":1,"op":1,"sum":"The Court held that the Fourth Amendment does not forbid a warrantless arrest for a minor criminal offense, such as a misdemeanor seatbelt violation punishable only by a fine. \"If an officer has probable cause to believe that an individual has committed even a very minor criminal offense in his presence, he may, without violating the Fourth Amendment, arrest the offender,\" wrote Justice Souter for the Court.","sumSrc":"Oyez","by":{"0":"35","2":"17"}},{"t":"case","label":"Beck v. Ohio","cite":"379 U.S. 89","y":1964,"id":"1964/18","sc":1,"sum":"No probable cause for petitioner's arrest having been shown, the arrest, and therefore necessarily the search for and seizure of the slips incident thereto, were invalid under the Fourth and Fourteenth Amendments. Pp. 91-97. 175 Ohio St. 73, 191 N. E. 2d 825, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"Big Horn County Elec. Coop., Inc. v. Adams","cite":"219 F.3d 944","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/219/944/","sum":"Describing the Crow Reservation as “a checkerboard pattern of land ownership,” “composed of fee land owned by non-Indians and members of the Tribe and trust land held by the United States in trust for the Tribe”.","sumSrc":"brief:0","by":{"0":"38"}},{"t":"case","label":"Brendale v. Confederated Tribes & Bands of the Yakima Indian Nation","cite":"492 U.S. 408","y":1989,"id":"1988/87-1622","sc":1,"op":2,"sum":"The treaty between the United States and the Yakima Indian Nation (Yakima Nation or Tribe) provided that the Tribe would retain its reservation for its \"exclusive use and benefit,\" and that \"no white man [shall] be permitted to reside upon the said reservation without [the Tribe's] permission.\" Much of the reservation is located in Yakima County, Washington. Roughly 80% of the reservation land is held in trust by …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32","1":"19"}},{"t":"case","label":"Bressi v. Ford","cite":"575 F.3d 891","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/575/891/","by":{"0":"8, 33"}},{"t":"case","label":"Clark v. Fort Peck Tribes","cite":"15 Am. Tribal Law 203","y":2018,"court":"Fort Peck Ct. App.","url":"https://www.courtlistener.com/c/Am.%20Tribal%20Law/15/203/","op":1,"by":{"0":"34"}},{"t":"case","label":"Colyer v. State","cite":"203 P.3d 1104","y":2009,"court":"Wyo.","url":"https://www.courtlistener.com/c/P.3d/203/1104/","by":{"0":"36"}},{"t":"case","label":"Duro v. Reina","cite":"495 U.S. 676","y":1990,"id":"1989/88-6546","sc":1,"op":4,"ar":3,"sum":"Noting the concern that tribal-court criminal jurisdiction over nonmembers would subject such defendants to “trial by political bodies that do not include them”.","sumSrc":"opinion","by":{"0":"3, 22, 23, 34","1":"passim","2":"11, 12, 13, 17"}},{"t":"case","label":"Florida v. Harris","cite":"568 U.S. 237","y":2013,"id":"2012/11-817","sc":1,"sum":"The Court found that police officers do not need to show evidence of a drug-detection dog's reliability to prove probable cause.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Heien v. North Carolina","cite":"574 U.S. 54","y":2014,"id":"2014/13-604","sc":1,"sum":"The Court decided that search and seizures are acceptable if a police officer made a reasonable factual or legal mistake.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Herrera v. Wyoming","cite":"139 S. Ct. 1686","y":2019,"id":"2018/17-532","sc":1,"sum":"Wyoming’s statehood did not abrogate the Crow Tribe’s 1868 federal treaty right to hunt on the “unoccupied lands of the United States”; the lands of the Bighorn National Forest did not become categorically “occupied” when the forest was created.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"2","2":"8"}},{"t":"case","label":"Manigault v. Springs","cite":"199 U.S. 473","y":1905,"id":"scdb/1905-037","sc":1,"sum":"In the absence of legislation by Congress, a State has full power to improve its lands and promote the general health by authorizing dams across interior streams, although previously navigable to the sea.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Merrion v. Jicarilla Apache Tribe","cite":"455 U.S. 130","y":1982,"id":"1980/80-11","sc":1,"sum":"Respondent Indian Tribe, pursuant to its Revised Constitution (which had been approved by the Secretary of the Interior (Secretary) as required by the Indian Reorganization Act of 1934), enacted an ordinance (also approved by the Secretary) imposing a severance tax on oil and gas production on the tribal reservation land. Oil and gas received by the Tribe as in-kind royalty payments from lessees of mineral leases on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26, 32"}},{"t":"case","label":"Miller v. United States","cite":"357 U.S. 301","y":1958,"id":"1957/126","sc":1,"sum":"Petitioner could not lawfully be arrested in his home by officers breaking in without first giving him notice of their authority and purpose, the arrest was unlawful, the evidence seized was inadmissible, and the conviction is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18","2":"3"}},{"t":"case","label":"Montana v. United States","cite":"450 U.S. 544","y":1981,"id":"1980/79-1128","sc":1,"op":11,"ar":23,"sum":"By a tribal regulation, the Crow Tribe of Montana sought to prohibit hunting and fishing within its reservation by anyone who is not a member of the Tribe. Relying on its purported ownership of the bed of the Big Horn River, on treaties which created its reservation, and on its inherent power as a sovereign, the Tribe claimed authority to prohibit hunting and fishing by nonmembers of the Tribe even on lands within …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 25, 26, 38","1":"11, 15, 16, 17, 24","2":"5, 11"}},{"t":"case","label":"Navarette v. California","cite":"572 U.S. 393","y":2014,"id":"2013/12-9490","sc":1,"ar":1,"sum":"The Court ruled that the Fourth Amendment does not require an officer who received information regarding drunken or reckless driving to independently corroborate the behavior before stopping the vehicle.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Negonsott v. Samuels","cite":"507 U.S. 99","y":1993,"id":"1992/91-5397","sc":1,"sum":"Petitioner Negonsott, a member of the Kickapoo Tribe and a resident of the Kickapoo Reservation in Kansas, was convicted by a County District Court jury of aggravated battery for shooting another Indian on the reservation. The court set aside the conviction on the ground that the Federal Government had exclusive jurisdiction to prosecute Negonsott for the shooting under the Indian Major Crimes Act, 18 U. S. C. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3"}},{"t":"case","label":"Oklahoma Tax Comm’n v. Citizen Band Potawatomi Tribe of Okla.","cite":"498 U.S. 505","y":1991,"id":"1990/89-1322","sc":1,"sum":"Under the doctrine of tribal sovereign immunity, a State that has not asserted jurisdiction over Indian lands under Public Law 280 may not tax sales of goods to tribesmen occurring on land held in trust for a federally recognized Indian tribe, but is free to collect taxes on such sales to nonmembers of the tribe.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Oliphant v. Suquamish Indian Tribe","cite":"435 U.S. 191","y":1978,"id":"1977/76-5729","sc":1,"op":3,"ar":1,"sum":"Indian tribal courts do not have inherent criminal jurisdiction to try and to punish non-Indians, and hence may not assume such jurisdiction unless specifically authorized to do so by Congress.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"11, 12, 15, 26, 38","2":"5, 11, 12, 13, 17"}},{"t":"case","label":"Ornelas v. United States","cite":"517 U.S. 690","y":1996,"id":"1995/95-5257","sc":1,"sum":"Announced by Chief Justice William H. Rehnquist, the Court held \"[t]he ultimate questions of reasonable suspicion and probable cause to make a warrantless search should be reviewed de novo.\" The principle details in such a review should be an analysis of events leading up to the search and the objective review of the search.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Plains Commerce Bank v. Long Family Land & Cattle Co.","cite":"554 U.S. 316","y":2008,"id":"2007/07-411","sc":1,"op":4,"ar":3,"sum":"Noting that nonmembers “have no part in tribal government” and have “no say in the laws and regulations that govern tribal territory”.","sumSrc":"opinion","by":{"0":"18, 22, 24, 25, 26, 37","1":"passim","2":"14"}},{"t":"case","label":"Seymour v. Superintendent of Wash. State Penitentiary","cite":"368 U.S. 351","y":1962,"id":"1961/62","sc":1,"sum":"The Colville Indian Reservation is still in existence; the land upon which the offense is alleged to have occurred is within the limits of that Reservation; the state courts had no jurisdiction to try petitioner for that offense; and the judgment denying habeas corpus is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"Solem v. Bartlett","cite":"465 U.S. 463","y":1984,"id":"1983/82-1253","sc":1,"sum":"The Act did not diminish the reservation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3"}},{"t":"case","label":"State v. Kurtz","cite":"249 P.3d 1271","y":2011,"court":"Or.","url":"https://www.courtlistener.com/c/P.3d/249/1271/","by":{"0":"46"}},{"t":"case","label":"State v. Madsen","cite":"760 N.W.2d 370","y":2009,"court":"S.D.","url":"https://www.courtlistener.com/c/N.W.2d/760/370/","by":{"0":"34"}},{"t":"case","label":"State v. Pamperien","cite":"967 P.2d 503","y":1998,"court":"Or. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/967/503/","op":1,"by":{"0":"36"}},{"t":"case","label":"State v. Railey","cite":"532 P.2d 204","y":1975,"court":"N.M. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/532/204/","by":{"0":"34"}},{"t":"case","label":"State v. Ryder","cite":"649 P.2d 756","y":1981,"court":"N.M. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/649/756/","op":1,"by":{"0":"36, 41"}},{"t":"case","label":"State v. Salazar","cite":"461 P.3d 946","y":2020,"court":"N.M. Ct. App.","url":"https://www.courtlistener.com/c/P.3d/461/946/","by":{"0":"39"}},{"t":"case","label":"State v. Schmuck","cite":"850 P.2d 1332","y":1993,"url":"https://www.courtlistener.com/c/P.2d/850/1332/","op":3,"sum":"Recognizing that a limited tribal power `to stop and detain alleged offenders in no way confers an unlimited authority to regulate the right of the public to travel on the Reservation's roads'.","sumSrc":"opinion","by":{"0":"24, 36, 37, 43, 46","1":"23"}},{"t":"case","label":"Strate v. A-1 Contractors","cite":"520 U.S. 438","y":1997,"id":"1996/95-1872","sc":1,"op":4,"ar":6,"sum":"Authored by Justice Ruth Bader Ginsburg, the Court ruled that when an accident occurs on a public highway maintained by the State pursuant to a federally granted right of way over Indian reservation land, a civil action against allegedly negligent nonmembers falls within state or federal regulatory and adjudicatory governance; absent a statute or treaty authorizing the tribe to govern the conduct of nonmembers driving on the State's highway, tribal courts may not exercise jurisdiction in such cases.","sumSrc":"Oyez","by":{"0":"12, 14, 21, 22, 24, 37","1":"15, 21, 22, 24, 25","2":"11, 13"}},{"t":"case","label":"Terry v. Ohio","cite":"392 U.S. 1","y":1968,"id":"1967/67","sc":1,"sum":"The Court found that police using a \"stop and frisk\" procedure are within their constitutional bounds as officers of the law.","sumSrc":"Oyez","by":{"0":"11, 34, 42"}},{"t":"case","label":"United States v. Brisk","cite":"171 F.3d 514","y":1999,"url":"https://www.courtlistener.com/c/F.3d/171/514/","by":{"0":"4"}},{"t":"case","label":"United States v. Bryant","cite":"136 S. Ct. 1954","y":2016,"id":"2015/15-420","sc":1,"sum":"The Court determined that the use of an uncounseled conviction in tribal court proceedings that complied with the Indian Civil Rights Act of 1968 (ICRA) as a predicate offense under 18 U.S.C. 117(a) did not violate the Sixth Amendment.","sumSrc":"Oyez","by":{"0":"3, 17, 45"}},{"t":"case","label":"United States v. Di Re","cite":"332 U.S. 581","y":1948,"id":"scdb/1947-021","sc":1,"sum":"The search was unlawful and the conviction cannot be sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18","1":"17, 18","2":"3"}},{"t":"case","label":"United States v. Hensley","cite":"469 U.S. 221","y":1985,"id":"1984/83-1330","sc":1,"sum":"Following an armed robbery in the Cincinnati suburb of St. Bernard, Ohio, a St. Bernard police officer, on the basis of information obtained from an informant that respondent had driven the getaway car during the robbery, issued a \"wanted flyer\" to other police departments in the area. The flyer stated that respondent was wanted for investigation of the robbery, described him and the date and location of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"United States v. John","cite":"437 U.S. 634","y":1978,"id":"1977/77-836","sc":1,"sum":"Lands designated as a reservation for Choctaw Indians residing in central Mississippi held, on the basis of the history of the relations between the Mississippi Choctaws and the United States, to be \"Indian country,\" as defined in 18 U. S. C. § 1151 (1976 ed.) to include \"all land within the limits of any Indian reservation under the jurisdiction of the United States Government,\" and as used in the Major Crimes Act, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3"}},{"t":"case","label":"United States v. Jorn","cite":"400 U.S. 470","y":1971,"id":"1970/19","sc":1,"sum":"The judgment is affirmed. Pp. 473-488. ifirmed. MR. JUSTICE HARLAN, joined by THE CImEF JUSTICE, MR. JUSTICE DouGLAS, and MR. JUSTICE MARSVALL, concluded that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"United States v. Lara","cite":"541 U.S. 193","y":2004,"id":"2003/03-107","sc":1,"ar":2,"sum":"In an opinion written by Justice Stephen G. Breyer and joined by Chief Justice Rehnquist and three other Justices, the Court found that the right to prosecute nonmember Indians is inherent in the sovereignty of Native American tribes.","sumSrc":"Oyez","by":{"0":"3, 20","1":"21"}},{"t":"case","label":"United States v. Lester","cite":"647 F.2d 869","y":1981,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/647/869/","by":{"0":"34"}},{"t":"case","label":"United States v. Mazurie","cite":"419 U.S. 544","y":1975,"id":"1974/73-1018","sc":1,"sum":"Respondents, who operated a bar on non-Indian land on the outskirts of an unincorporated village within the Wind River Reservation and who had been denied a tribal liquor license by the Wind River Tribes pursuant to their option under 18 U. S. C. § 1161 to regulate the introduction of liquor into Indian country, were convicted at a nonjury trial of introducing spirituous beverages into Indian country in violation of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 32","1":"15"}},{"t":"case","label":"United States v. Smith","cite":"899 F.2d 116","y":1990,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/899/116/","sum":"Rejecting claim that “state police lacked ‘authority’ to seize [a] weapon” that “they reasonably believe[d] constitute[d] evidence of a federal crime”.","sumSrc":"brief:2","by":{"0":"18","1":"17, 18","2":"4"}},{"t":"case","label":"United States v. Terry","cite":"400 F.3d 575","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/400/575/","op":1,"by":{"0":"46"}},{"t":"case","label":"United States v. Wheeler","cite":"435 U.S. 313","y":1978,"id":"1977/76-1629","sc":1,"op":2,"sum":"The Double Jeopardy Clause does not bar the federal prosecution.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"16, 21","2":"4, 5, 10, 11, 16"}},{"t":"case","label":"United States v. Winans","cite":"198 U.S. 371","y":1905,"id":"scdb/1904-073","sc":1,"sum":"This court will construe a treaty with Indians as they understood it and as justice and reason demand.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Washington v. Confederated Tribes of Colville Indian Reservation","cite":"447 U.S. 134","y":1980,"id":"1979/78-630","sc":1,"op":1,"sum":"These cases concern challenges of several Indian Tribes to efforts by the State of Washington to apply various state taxes and other laws to transactions and activities occurring on Indian reservations. Washington imposes a cigarette excise tax on the \"sale, use, consumption, handling, possession or distribution\" of cigarettes within the State. It also imposes a general retail sales tax on sales of personal …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19","1":"11, 18, 19","2":"5, 10"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"0":"passim"}},{"t":"usc","label":"26 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/26/1301","by":{"0":"3, 21"}},{"t":"usc","label":"25 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/25/1301","subs":["(2)"],"stext":{"head":"§1301. Definitions","paras":[[0,"For purposes of this subchapter, the term—"],[0,"(1) \"Indian tribe\" means any tribe, band, or other group of Indians subject to the jurisdiction of the United States and recognized as possessing powers of self-government;"],[0,"(2) \"powers of self-government\" means and includes all governmental powers possessed by an Indian tribe, executive, legislative, and judicial, and all offices, bodies, and tribunals by and through which they are executed, including courts of Indian offenses; and means the inherent power of Indian tribes, hereby recognized and affirmed, to exercise criminal jurisdiction over all Indians;"],[0,"(3) \"Indian court\" means any Indian tribal court or court of Indian offense; and"],[0,"(4) \"Indian\" means any person who would be subject to the jurisdiction of the United States as an Indian under section 1153, title 18, if that person were to commit an offense listed in that section in Indian country to which that section applies."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/1301?type=usc&year=mostrecent&link-type=html"},"head":"§1301. Definitions","tname":"Indians","by":{"0":"3, 21","1":"8, 37","2":"9"}},{"t":"usc","label":"25 U.S.C. § 1302","url":"https://www.law.cornell.edu/uscode/text/25/1302","subs":["(a)(2)"],"stext":{"head":"§1302. Constitutional rights","paras":[[0,"(a) In general"],[0,"No Indian tribe in exercising powers of self-government shall—"],[1,"(1) make or enforce any law prohibiting the free exercise of religion, or abridging the freedom of speech, or of the press, or the right of the people peaceably to assemble and to petition for a redress of grievances;"],[1,"(2) violate the right of the people to be secure in their persons, houses, papers, and effects against unreasonable search and seizures, nor issue warrants, but upon probable cause, supported by oath or affirmation, and particularly describing the place to be searched and the person or thing to be seized;"],[1,"(3) subject any person for the same offense to be twice put in jeopardy;"],[1,"(4) compel any person in any criminal case to be a witness against himself;"],[1,"(5) take any private property for a public use without just compensation;"],[1,"(6) deny to any person in a criminal proceeding the right to a speedy and public trial, to be informed of the nature and cause of the accusation, to be confronted with the witnesses against him, to have compulsory process for obtaining witnesses in his favor, and at his own expense to have the assistance of counsel for his defense (except as provided in subsection (b));"],[1,"(7)(A) require excessive bail, impose excessive fines, or inflict cruel and unusual punishments;"],[1,"(B) except as provided in subparagraph (C), impose for conviction of any 1 offense any penalty or punishment greater than imprisonment for a term of 1 year or a fine of $5,000, or both;"],[1,"(C) subject to subsection (b), impose for conviction of any 1 offense any penalty or punishment greater than imprisonment for a term of 3 years or a fine of $15,000, or both; or"],[1,"(D) impose on a person in a criminal proceeding a total penalty or punishment greater than imprisonment for a term of 9 years;"],[1,"(8) deny to any person within its jurisdiction the equal protection of its laws or deprive any person of liberty or property without due process of law;"],[1,"(9) pass any bill of attainder or ex post facto law; or"],[1,"(10) deny to any person accused of an offense punishable by imprisonment the right, upon request, to a trial by jury of not less than six persons."],[0,"(b) Offenses subject to greater than 1-year imprisonment or a fine greater than $5,000"],[0,"A tribal court may subject a defendant to a term of imprisonment greater than 1 year but not to exceed 3 years for any 1 offense, or a fine greater than $5,000 but not to exceed $15,000, or both, if the defendant is a person accused of a criminal offense who—"],[1,"(1) has been previously convicted of the same or a comparable offense by any jurisdiction in the United States; or"],[1,"(2) is being prosecuted for an offense comparable to an offense that would be punishable by more than 1 year of imprisonment if prosecuted by the United States or any of the States."],[0,"(c) Rights of defendants"],[0,"In a criminal proceeding in which an Indian tribe, in exercising powers of self-government, imposes a total term of imprisonment of more than 1 year on a defendant, the Indian tribe shall—"],[1,"(1) provide to the defendant the right to effective assistance of counsel at least equal to that guaranteed by the United States Constitution; and"],[1,"(2) at the expense of the tribal government, provide an indigent defendant the assistance of a defense attorney licensed to practice law by any jurisdiction in the United States that applies appropriate professional licensing standards and effectively ensures the competence and professional responsibility of its licensed attorneys;"],[1,"(3) require that the judge presiding over the criminal proceeding—"],[2,"(A) has sufficient legal training to preside over criminal proceedings; and"],[2,"(B) is licensed to practice law by any jurisdiction in the United States;"],[1,"(4) prior to charging the defendant, make publicly available the criminal laws (including regulations and interpretative documents), rules of evidence, and rules of criminal procedure (including rules governing the recusal of judges in appropriate circumstances) of the tribal government; and"],[1,"(5) maintain a record of the criminal proceeding, including an audio or other recording of the trial proceeding."],[0,"(d) Sentences"],[0,"In the case of a defendant sentenced in accordance with subsections (b) and (c), a tribal court may require the defendant—"],[1,"(1) to serve the sentence—"],[2,"(A) in a tribal correctional center that has been approved by the Bureau of Indian Affairs for long-term incarceration, in accordance with guidelines to be developed by the Bureau of Indian Affairs (in consultation with Indian tribes) not later than 180 days after July 29, 2010;"],[2,"(B) in the nearest appropriate Federal facility, at the expense of the United States pursuant to the Bureau of Prisons tribal prisoner pilot program described in section 304(c) 1 of the Tribal Law and Order Act of 2010;"],[2,"(C) in a State or local government-approved detention or correctional center pursuant to an agreement between the Indian tribe and the State or local government; or"],[2,"(D) in an alternative rehabilitation center of an Indian tribe; or"],[1,"(2) to serve another alternative form of punishment, as determined by the tribal court judge pursuant to tribal law."],[0,"(e) Definition of offense"],[0,"In this section, the term \"offense\" means a violation of a criminal law."],[0,"(f) Effect of section"],[0,"Nothing in this section affects the obligation of the United States, or any State government that has been delegated authority by the United States, to investigate and prosecute any criminal violation in Indian country."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/1302?type=usc&year=mostrecent&link-type=html"},"head":"§1302. Constitutional rights","tname":"Indians","by":{"0":"8, 21, 34","1":"37, 38","2":"9"}},{"t":"usc","label":"18 U.S.C. § 13","url":"https://www.law.cornell.edu/uscode/text/18/13","by":{"0":"3"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(c)(1)(A)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§924. Penalties","tname":"Crimes and Criminal Procedure","by":{"0":"2, 8"}},{"t":"usc","label":"18 U.S.C. § 1151","url":"https://www.law.cornell.edu/uscode/text/18/1151","subs":["(a)"],"stext":{"head":"§1151. Indian country defined","paras":[[0,"Except as otherwise provided in sections 1154 and 1156 of this title, the term \"Indian country\", as used in this chapter, means (a) all land within the limits of any Indian reservation under the jurisdiction of the United States Government, notwithstanding the issuance of any patent, and, including rights-of-way running through the reservation, (b) all dependent Indian communities within the borders of the United States whether within the original or subsequently acquired territory thereof, and whether within or without the limits of a state, and (c) all Indian allotments, the Indian titles to which have not been extinguished, including rights-of-way running through the same."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1151?type=usc&year=mostrecent&link-type=html"},"head":"§1151. Indian country defined","tname":"Crimes and Criminal Procedure","by":{"0":"39, 2, 21, 28, 20","1":"23","2":"9, 10"}},{"t":"usc","label":"18 U.S.C. § 1152","url":"https://www.law.cornell.edu/uscode/text/18/1152","stext":{"head":"§1152. Laws governing","paras":[[0,"Except as otherwise expressly provided by law, the general laws of the United States as to the punishment of offenses committed in any place within the sole and exclusive jurisdiction of the United States, except the District of Columbia, shall extend to the Indian country."],[0,"This section shall not extend to offenses committed by one Indian against the person or property of another Indian, nor to any Indian committing any offense in the Indian country who has been punished by the local law of the tribe, or to any case where, by treaty stipulations, the exclusive jurisdiction over such offenses is or may be secured to the Indian tribes respectively."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1152?type=usc&year=mostrecent&link-type=html"},"head":"§1152. Laws governing","tname":"Crimes and Criminal Procedure","by":{"0":"3","1":"23","2":"9, 10"}},{"t":"usc","label":"18 U.S.C. § 1153","url":"https://www.law.cornell.edu/uscode/text/18/1153","by":{"0":"3"}},{"t":"usc","label":"18 U.S.C. § 1162","url":"https://www.law.cornell.edu/uscode/text/18/1162","by":{"0":"3"}},{"t":"usc","label":"18 U.S.C. § 1951","url":"https://www.law.cornell.edu/uscode/text/18/1951","by":{"0":"20"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(a)(1)"],"stext":{"head":"§841. Prohibited acts A","paras":[[0,"(a) Unlawful acts"],[0,"Except as authorized by this subchapter, it shall be unlawful for any person knowingly or intentionally—"],[1,"(1) to manufacture, distribute, or dispense, or possess with intent to manufacture, distribute, or dispense, a controlled substance; or"],[1,"(2) to create, distribute, or dispense, or possess with intent to distribute or dispense, a counterfeit substance."],[0,"(b) Penalties"],[0,"Except as otherwise provided in section 849, 859, 860, or 861 of this title, any person who violates subsection (a) of this section shall be sentenced as follows:"],[0,"(1)(A) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 1 kilogram or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 5 kilograms or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 280 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 100 grams or more of phencyclidine (PCP) or 1 kilogram or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 10 grams or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 400 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 100 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 1000 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 1,000 or more marihuana plants regardless of weight; or"],[1,"(viii) 50 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 500 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 10 years or more than life and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $10,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment of not less than 15 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $20,000,000 if the defendant is an individual or $75,000,000 if the defendant is other than an individual, or both. If any person commits a violation of this subparagraph or of section 849, 859, 860, or 861 of this title after 2 or more prior convictions for a serious drug felony or serious violent felony have become final, such person shall be sentenced to a term of imprisonment of not less than 25 years and fined in accordance with the preceding sentence. Notwithstanding section 3583 of title 18, any sentence under this subparagraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 5 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 10 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(B) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 100 grams or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 500 grams or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 28 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 10 grams or more of phencyclidine (PCP) or 100 grams or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 1 gram or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 40 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 10 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 100 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 100 or more marihuana plants regardless of weight; or"],[1,"(viii) 5 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 50 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 5 years and not more than 40 years and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $5,000,000 if the defendant is an individual or $25,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment which may not be less than 10 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $8,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposed under this subparagraph shall, in the absence of such a prior conviction, include a term of supervised release of at least 4 years in addition to such term of imprisonment and shall, if there was such a prior conviction, include a term of supervised release of at least 8 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(C) In the case of a controlled substance in schedule I or II, gamma hydroxybutyric acid (including when scheduled as an approved drug product for purposes of section 3(a)(1)(B) of the Hillory J. Farias and Samantha Reid Date-Rape Drug Prohibition Act of 2000), or 1 gram of flunitrazepam, except as provided in subparagraphs (A), (B), and (D), such person shall be sentenced to a term of imprisonment of not more than 20 years and if death or serious bodily injury results from the use of such substance shall be sentenced to a term of imprisonment of not less than twenty years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $1,000,000 if the defendant is an individual or $5,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a felony drug offense has become final, such person shall be sentenced to a term of imprisonment of not more than 30 years and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $2,000,000 if the defendant is an individual or $10,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposing a term of imprisonment under this paragraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 3 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 6 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under the provisions of this subparagraph which provide for a mandatory term of imprisonment if death or serious bodily injury results, nor shall a person so sentenced be eligible for parole during the term of such a sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/841?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§841. Prohibited acts A","tname":"Food and Drugs","by":{"0":"20, 2, 8"}},{"t":"case","label":"Begay v. United States","cite":"219 Ct. Cl. 599","y":1979,"url":"https://www.courtlistener.com/c/Ct.%20Cl./219/599/","by":{"1":"35"}},{"t":"case","label":"Begay v. United States","cite":"224 Ct. Cl. 712","y":1980,"url":"https://www.courtlistener.com/c/Ct.%20Cl./224/712/","by":{"1":"35"}},{"t":"case","label":"Cheyenne & Arapaho Tribes v. United States","cite":"2020 WL 7251080","y":2020,"court":"Fed. Cl. Dec. 9","by":{"1":"34"}},{"t":"case","label":"Elk v. United States","cite":"87 Fed. Cl. 70","y":2009,"url":"https://www.courtlistener.com/c/Fed.%20Cl./87/70/","by":{"1":"35"}},{"t":"case","label":"Hebah v. United States","cite":"428 F.2d 1334","y":1970,"court":"Ct. Cl.","url":"https://www.courtlistener.com/c/F.2d/428/1334/","by":{"1":"34"}},{"t":"case","label":"Jones v. United States","cite":"846 F.3d 1343","y":2017,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/846/1343/","by":{"1":"35"}},{"t":"case","label":"Kokkonen v. Guardian Life Ins. Co. of America","cite":"511 U.S. 375","y":1994,"id":"1993/93-263","sc":1,"sum":"A federal district court, possessing only that power authorized by Constitution and statute, lacks jurisdiction over a claim for breach of a contract, part of the consideration for which was dismissal of an earlier federal suit. No federal statute makes that connection (if it constitutionally could) the basis for federal-court jurisdiction over the contract dispute. Moreover, the doctrine of ancillary jurisdiction …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"McGirt v. Oklahoma","cite":"140 S. Ct. 2452","y":2020,"id":"2019/18-9526","sc":1,"sum":"The Court held that parts of eastern Oklahoma are an Indian reservation subject to exclusive federal jurisdiction for certain crimes under the Indian Major Crimes Act.","sumSrc":"Oyez","by":{"1":"12, 25, 26"}},{"t":"case","label":"Michigan v. Bay Mills Indian Cmty.","cite":"572 U.S. 782","y":2014,"id":"2013/12-515","sc":1,"op":1,"sum":"The Court held that Indian tribes have sovereign immunity that can only be revoked by Congress, and that the immunity extends to their commercial activities, even if they are not on their protected land.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Nevada v. Hicks","cite":"533 U.S. 353","y":2001,"id":"2000/99-1994","sc":1,"op":1,"sum":"A unanimous Court held that \"[b]ecause the Fallon Paiute-Shoshone Tribes lacked legislative authority to restrict, condition, or otherwise regulate the ability of state officials to investigate off-reservation violations of state law, they also lacked adjudicative authority to hear respondent's claim that those officials violated tribal law in the performance of their duties. \"[S]ince the lack of authority is clear,\" continued Scalia, \"there is no need to exhaust the jurisdictional dispute in tribal court.","sumSrc":"Oyez","by":{"1":"13, 16, 37"}},{"t":"case","label":"Richard v. United States","cite":"677 F.3d 1141","y":2012,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/677/1141/","by":{"1":"35"}},{"t":"case","label":"Singelton v. Wulff","cite":"428 U.S. 106","y":1976,"id":"1975/74-1393","sc":1,"sum":"The judgment is reversed and the case is remanded. Pp. 112-121; 121-122; 122. 508 F. 2d 1211, reversed and remanded. MR. JUSTICE BLACKMUN delivered the opinion of the Court with respect to Parts I, II-A, and III, finding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"South Dakota v. Bourland","cite":"508 U.S. 679","y":1993,"id":"1992/91-2051","sc":1,"op":1,"ar":1,"sum":"Congress, in the Flood Control and Cheyenne River Acts, abrogated the Tribe's rights under the Fort Laramie Treaty to regulate non-Indian hunting and fishing on lands taken by the United States for construction of the Oahe Dam and Reservoir.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Tsosie v. United States","cite":"825 F.2d 393","y":1987,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/825/393/","by":{"1":"35"}},{"t":"case","label":"United States v. Lopez","cite":"514 U.S. 549","y":1995,"id":"1994/93-1260","sc":1,"sum":"The Court found the 1990 Gun-Free School Zones Act unconstitutional for overstepping the congressional boundaries of the Commerce Clause.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"United States v. Morrison","cite":"529 U.S. 598","y":2000,"id":"1999/99-5","sc":1,"sum":"The Court found that sections of the Violence Against Women Act were unconstitutional under the Commerce Clause.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"usc","label":"21 U.S.C. § 878","url":"https://www.law.cornell.edu/uscode/text/21/878","subs":["(a)(3)"],"stext":{"head":"§878. Powers of enforcement personnel","paras":[[0,"(a) Any officer or employee of the Drug Enforcement Administration or any State, tribal, or local law enforcement officer designated by the Attorney General may—"],[1,"(1) carry firearms;"],[1,"(2) execute and serve search warrants, arrest warrants, administrative inspection warrants, subpenas, and summonses issued under the authority of the United States;"],[1,"(3) make arrests without warrant (A) for any offense against the United States committed in his presence, or (B) for any felony, cognizable under the laws of the United States, if he has probable cause to believe that the person to be arrested has committed or is committing a felony;"],[1,"(4) make seizures of property pursuant to the provisions of this subchapter; and"],[1,"(5) perform such other law enforcement duties as the Attorney General may designate."],[0,"(b) State and local law enforcement officers performing functions under this section shall not be deemed Federal employees and shall not be subject to provisions of law relating to Federal employees, except that such officers shall be subject to section 3374(c) of title 5."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/878?type=usc&year=mostrecent&link-type=html"},"head":"§878. Powers of enforcement personnel","tname":"Food and Drugs","by":{"1":"29, 30","2":"18"}},{"t":"usc","label":"25 U.S.C. § 2801","url":"https://www.law.cornell.edu/uscode/text/25/2801","subs":["(7)"],"by":{"1":"28"}},{"t":"usc","label":"25 U.S.C. § 2803","url":"https://www.law.cornell.edu/uscode/text/25/2803","subs":["(3)","(5)"],"stext":{"head":"§2803. Law enforcement authority","paras":[[0,"The Secretary may charge employees of the Bureau with law enforcement responsibilities and may authorize those employees to—"],[1,"(1) carry firearms;"],[1,"(2) execute or serve warrants, summonses, or other orders relating to a crime committed in Indian country and issued under the laws of—"],[2,"(A) the United States (including those issued by a Court of Indian Offenses under regulations prescribed by the Secretary or offenses processed by the Central Violations Bureau); or"],[2,"(B) an Indian tribe if authorized by the Indian tribe;"],[1,"(3) make an arrest without a warrant for an offense committed in Indian country if—"],[2,"(A) the offense is committed in the presence of the employee,1"],[2,"(B) the offense is a felony and the employee has probable cause to believe that the person to be arrested has committed, or is committing, the felony;"],[2,"(C) the offense is a misdemeanor crime of domestic violence, dating violence, stalking, or violation of a protection order and has, as an element, the use or attempted use of physical force, or the threatened use of a deadly weapon, committed by a current or former spouse, parent, or guardian of the victim, by a person with whom the victim shares a child in common, by a person who is cohabitating with or has cohabited with the victim as a spouse, parent, or guardian, or by a person similarly situated to a spouse, parent or guardian of the victim, and the employee has probable cause to believe that the person to be arrested has committed, or is committing the crime; or"],[2,"(D)(i) the offense involves—"],[3,"(I) a misdemeanor controlled substance offense in violation of—"],[4,"(aa) the Controlled Substances Act (21 U.S.C. 801 et seq.);"],[4,"(bb) title IX of the Personal Responsibility and Work Opportunity Reconciliation Act of 1996 (21 U.S.C. 862a et seq.); 2 or"],[4,"(cc) section 865 of title 21;"],[3,"(II) a misdemeanor firearms offense in violation of chapter 44 of title 18;"],[3,"(III) a misdemeanor assault in violation of chapter 7 of title 18; or"],[3,"(IV) a misdemeanor liquor trafficking offense in violation of chapter 59 of title 18; and"],[2,"(ii) the employee has probable cause to believe that the individual to be arrested has committed, or is committing, the crime;"],[1,"(4) offer and pay a reward for services or information, or purchase evidence, assisting in the detection or investigation of the commission of an offense committed in Indian country or in the arrest of an offender against the United States;"],[1,"(5) make inquiries of any person, and administer to, or take from, any person an oath, affirmation, or affidavit, concerning any matter relevant to the enforcement or carrying out in Indian country of a law of either the United States or an Indian tribe that has authorized the employee to enforce or carry out tribal laws;"],[1,"(6) wear a prescribed uniform and badge or carry prescribed credentials;"],[1,"(7) perform any other law enforcement related duty; and"],[1,"(8) when requested, assist (with or without reimbursement) any Federal, tribal, State, or local law enforcement agency in the enforcement or carrying out of the laws or regulations the agency enforces or administers."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/2803?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2803. Law enforcement authority","tname":"Indians","by":{"1":"28, 29","2":"18, 18, 18"}},{"t":"usc","label":"25 U.S.C. § 2804","url":"https://www.law.cornell.edu/uscode/text/25/2804","subs":["(a)(2)","(a)(3)(A)","(a)(3)(B)(ii)"],"stext":{"head":"§2804. Assistance by other agencies","paras":[[0,"(a) Agreements"],[0,"(1) In general"],[1,"Not later than 180 days after July 29, 2010, the Secretary shall establish procedures to enter into memoranda of agreement for the use (with or without reimbursement) of the personnel or facilities of a Federal, tribal, State, or other government agency to aid in the enforcement or carrying out in Indian country of a law of either the United States or an Indian tribe that has authorized the Secretary to enforce tribal laws."],[0,"(2) Certain activities"],[1,"The Secretary may authorize a law enforcement officer of such an agency to perform any activity the Secretary may authorize under section 2803 of this title."],[0,"(3) Program enhancement"],[0,"(A) Training sessions in Indian country"],[0,"(i) In general"],[3,"The procedures described in paragraph (1) shall include the development of a plan to enhance the certification and provision of special law enforcement commissions to tribal law enforcement officials, and, subject to subsection (d), State and local law enforcement officials, pursuant to this section."],[0,"(ii) Inclusions"],[3,"The plan under clause (i) shall include the hosting of regional training sessions in Indian country, not less frequently than biannually, to educate and certify candidates for the special law enforcement commissions."],[0,"(B) Memoranda of agreement"],[0,"(i) In general"],[3,"Not later than 180 days after July 29, 2010, the Secretary, in consultation with Indian tribes and tribal law enforcement agencies, shall develop minimum requirements to be included in special law enforcement commission agreements pursuant to this section."],[0,"(ii) Substance of agreements"],[3,"Each agreement entered into pursuant to this section shall reflect the status of the applicable certified individual as a Federal law enforcement officer under subsection (f), acting within the scope of the duties described in section 2802(c) of this title."],[0,"(iii) Agreement"],[3,"Not later than 60 days after the date on which the Secretary determines that all applicable requirements under clause (i) are met, the Secretary shall offer to enter into a special law enforcement commission agreement with the Indian tribe."],[0,"(b) Agreement to be in accord with agreements between Secretary and Attorney General"],[0,"Any agreement entered into under this section relating to the enforcement of the criminal laws of the United States shall be in accord with any agreement between the Secretary and the Attorney General of the United States."],[0,"(c) Limitations on use of personnel of non-Federal agency"],[0,"The Secretary may not use the personnel of a non-Federal agency under this section in an area of Indian country if the Indian tribe having jurisdiction over such area of Indian country has adopted a resolution objecting to the use of the personnel of such agency. The Secretary shall consult with Indian tribes before entering into any agreement under subsection (a) with a non-Federal agency that will provide personnel for use in any area under the jurisdiction of such Indian tribes."],[0,"(d) Authority of Federal agency head to enter into agreement with Secretary"],[0,"Notwithstanding the provisions of section 1535 of title 31, the head of a Federal agency with law enforcement personnel or facilities may enter into an agreement (with or without reimbursement) with the Secretary under subsection (a)."],[0,"(e) Authority of Federal agency head to enter into agreement with Indian tribe"],[0,"The head of a Federal agency with law enforcement personnel or facilities may enter into an agreement (with or without reimbursement) with an Indian tribe relating to—"],[1,"(1) the law enforcement authority of the Indian tribe, or"],[1,"(2) the carrying out of a law of either the United States or the Indian tribe."],[0,"(f) Status of person as Federal employee"],[0,"While acting under authority granted by the Secretary under subsection (a), a person who is not otherwise a Federal employee shall be considered to be—"],[1,"(1) an employee of the Department of the Interior only for purposes of—"],[2,"(A) the provisions of law described in section 3374(c)(2) of title 5, and"],[2,"(B) sections 111 and 1114 of title 18, and"],[1,"(2) an eligible officer under subchapter III of chapter 81 of title 5."],[0,"(g) Acceptance of assistance"],[0,"The Bureau may accept reimbursement, resources, assistance, or funding from—"],[1,"(1) a Federal, tribal, State, or other government agency; or"],[1,"(2) the Indian Law Enforcement Foundation established under section 5412(a) 1 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/2804?type=usc&year=mostrecent&link-type=html"},"head":"§2804. Assistance by other agencies","tname":"Indians","by":{"1":"28, 29","2":"18, 19, 19, 18, 18"}},{"t":"usc","label":"25 U.S.C. § 2805","url":"https://www.law.cornell.edu/uscode/text/25/2805","stext":{"head":"§2805. Regulations","paras":[[0,"After consultation with the Attorney General of the United States, the Secretary may prescribe under this chapter regulations relating to the enforcement of criminal laws of the United States and regulations relating to the consideration of applications for contracts awarded under the Indian Self-Determination Act [25 U.S.C. 5321 et seq.] to perform the functions of the Branch of Criminal Investigations."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/2805?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2805. Regulations","tname":"Indians","by":{"1":"29"}},{"t":"reg","label":"25 C.F.R. § 12.21","url":"https://www.ecfr.gov/current/title-25/section-12.21","by":{"1":"29"}},{"t":"case","label":"Arizona v. San Carlos Apache Tribe","cite":"463 U.S. 545","y":1983,"id":"1982/81-2147","sc":1,"sum":"In ColoradoRiver Water ConservationDistrictv. United States, 424 U. S. 800, it was held that (1) the McCarran Amendment, which waived the sovereign immunity of the United States as to comprehensive state water rights adjudications, provides state courts with jurisdiction to adjudicate Indian water rights held in trust by the United States, and (2), in light of the federal policies underlying that Amendment, a suit …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"Brendale v. Confederated Tribes & Bands of the Yakima Indian Nation","cite":"492 U.S. 406","y":1989,"id":"1988/88-309","sc":1,"op":1,"sum":"Explaining how the Court’s decisions harmonize with the principle.","sumSrc":"brief:2","by":{"2":"6"}},{"t":"case","label":"Commonwealth v. Craan","cite":"13 N.E.3d 569","y":2014,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E.3d/13/569/","sum":"Explaining that the “authority” of “ ‘local police’ ” to “ ‘enforc[e] federal statutes’ ” “derives from State law”.","sumSrc":"brief:2","by":{"2":"4"}},{"t":"case","label":"Gonzales v. City of Peoria","cite":"722 F.2d 468","y":1983,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/722/468/","by":{"2":"4"}},{"t":"case","label":"Johnson v. United States","cite":"333 U.S. 10","y":1948,"id":"scdb/1947-031","sc":1,"by":{"2":"3"}},{"t":"case","label":"Ker v. California","cite":"374 U.S. 23","y":1963,"id":"1962/53","sc":1,"sum":"The judgment is affirmed. Pp. 34-44. 195 Cal. App. 2d 246, 15 Cal. Rptr. 767, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"3"}},{"t":"case","label":"(I) Cases—Continued: New Mexico v. Mescalero Apache Tribe","cite":"462 U.S. 324","y":1983,"id":"1982/82-331","sc":1,"sum":"The application of New Mexico's laws to on-reservation hunting and fishing by nonmembers of the Tribe is pre-empted by the operation of federal law.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"People v. LaFontaine","cite":"705 N.E.2d 663","y":1998,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/705/663/","by":{"2":"4"}},{"t":"case","label":"United States v. Bowdach","cite":"561 F.2d 1160","y":1977,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/561/1160/","by":{"2":"4"}},{"t":"case","label":"United States v. Janik","cite":"723 F.2d 537","y":1983,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/723/537/","by":{"2":"4"}},{"t":"case","label":"United States v. Turner","cite":"553 F.3d 1337","y":2009,"url":"https://www.courtlistener.com/c/F.3d/553/1337/","sum":"Rejecting claim that “because possession of ammunition is not a crime under state law, state law enforcement could not seize the ammunition and detain [the defendant] on that basis”.","sumSrc":"brief:2","by":{"2":"4"}},{"t":"case","label":"Virginia v. Moore","cite":"553 U.S. 164","y":2008,"id":"2007/06-1082","sc":1,"sum":"The Court held unanimously that the search did not violate Moore's constitutional rights. Writing for an eight justice majority (with Justice Ruth Bader Ginsburg concurring), Justice Antonin Scalia stated that the existence of probable cause gives an arresting officer the right to perform a reasonable search of the accused to ensure the officer's safety and to safeguard evidence.","sumSrc":"Oyez","by":{"2":"3"}},{"t":"const","label":"Article IV, Section 2, Clause 2","text":"A Person charged in any State with Treason, Felony, or other Crime, who shall flee from Justice, and be found in another State, shall on Demand of the executive Authority of the State from which he fled, be delivered up, to be removed to the State having Jurisdiction of the Crime.","by":{"2":"2, 6"}},{"t":"const","label":"Article V","clauses":[["article-v","Article V: Amending the Constitution"]],"text":"The Congress, whenever two thirds of both Houses shall deem it necessary, shall propose Amendments to this Constitution, or, on the Application of the Legislatures of two thirds of the several States, shall call a Convention for proposing Amendments, which, in either Case, shall be valid to all Intents and Purposes, as Part of this Constitution, when ratified by the Legislatures of three fourths of the several States, or by Conventions in three fourths thereof, as the one or the other Mode of Ratification may be proposed by the Congress; Provided that no Amendment which may be made prior to the Year One thousand eight hundred and eight shall in any Manner affect the first and fourth Clauses in the Ninth Section of the first Article; and that no State, without its Consent, shall be deprived of its equal Suffrage in the Senate.","by":{"2":"7, 8"}},{"t":"const","label":"Article VI","clauses":[["supremacy","Supremacy Clause"],["religious-test","No Religious Test Clause"]],"text":"All Debts contracted and Engagements entered into, before the Adoption of this Constitution, shall be as valid against the United States under this Constitution, as under the Confederation. This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding. The Senators and Representatives before mentioned, and the Members of the several State Legislatures, and all executive and judicial Officers, both of the United States and of the several States, shall be bound by Oath or Affirmation, to support this Constitution; but no religious Test shall ever be required as a Qualification to any Office or public Trust under the United States.","by":{"2":"7"}},{"t":"usc","label":"5 U.S.C. § 3374","url":"https://www.law.cornell.edu/uscode/text/5/3374","subs":["(c)(2)"],"by":{"2":"18"}},{"t":"usc","label":"5 U.S.C. § 8191","url":"https://www.law.cornell.edu/uscode/text/5/8191","by":{"2":"18"}}]};